local _, WFJ = ...
WFJ.Data.add("book", {
  ["ee3192ff814e413e"] = { "Sono passati quasi mille anni dalla «Guerra delle Sabbie Mutevoli». Fu durante questa guerra, nel cuore del deserto di ⟦Silithus=Silitus⟧, che una grande tragedia e un fardello ancora più grande si abbatterono su Fandral Staghelm. Si ritiene che gli eventi qui descritti siano ciò che alla fine plasmò l'indole sgradevole dell'arcidruido.", "." },
  ["ee400f0c03a11131"] = { "Giorno 2\n\nLa ricerca continua, e del minerale nessuna traccia. Comincio a chiedermi se Stonegear non si sia inventato la voce di quel minerale per scherzo. Be', se l'ha fatto, quando torno allo ⟦Steelgrill's Depot=Scalo di Grigliafredda⟧ si ritroverà con il cranio spaccato!\n\nStanotte, mentre preparavo il campo, ho sentito un ringhio echeggiare tra i canyon.\n\nNon è un lupo. Forse è un orso.", "." },
  ["ee44180f3d814d16"] = { "Mentre Medivh si adoperava per convincere orchi e umani della necessità di un'alleanza, gli elfi della notte combattevano la Legione a modo loro, nell'ombra. Tyrande Whisperwind, l'immortale somma sacerdotessa delle ⟦Sentinels=Sentinelle⟧ degli elfi della notte, lottò disperatamente per impedire a demoni e non morti di invadere le foreste di ⟦Ashenvale=Valtetra⟧. Tyrande capì di avere bisogno di aiuto, così partì per risvegliare i druidi degli elfi della notte dal loro sonno millenario.", "." },
  ["ee7a9790ece63b7a"] = { "Oltre a condurre le energie del rituale, la Bell, la Wheel e la Candle hanno proprietà uniche.\n\nLa Bell of Dethmoora, quando suona, infonde vigore ed energia agli stregoni all'interno del cerchio.\n\nLa Wheel of the Black March, quando gira, protegge dai danni chi si trova nel cerchio.\n\nLa Doomsday Candle, quando arde, scaglia un'energia occulta contro i nemici che entrano nel cerchio.\n\nPer via di questi benefici, è molto importante mantenere in funzione tutti questi oggetti durante il rituale.", "." },
  ["ee9d063b62257c5a"] = { "Nel frattempo, nelle terre del sud dilaniate dalla guerra, i resti dispersi dell'⟦Horde=Orda⟧ lottavano per la loro stessa sopravvivenza. Sebbene Grom Hellscream e il suo clan ⟦Warsong=Cantaguerra⟧ fossero riusciti a sfuggire alla cattura, Deadeye e il suo clan Bleeding Hollow furono radunati e rinchiusi nei campi di internamento di Lordaeron. Nonostante queste costose rivolte, i sorveglianti dei campi ristabilirono presto il controllo sui loro brutali prigionieri.", "." },
  ["eea5c4ff35da67b0"] = { "Un avvertimento per chi caccia: questi demoni vanno affrontati alle loro condizioni. Se capiscono di non esserti superiori, fuggiranno.\n\nNIENTE COMPAGNI.", "." },
  ["eebb007b69acb0cb"] = { "--Primo giorno--\n\nIl mio viaggio da ⟦Ironforge=Forgiardente⟧ mi porta finalmente a Kalimdor!\n\nIl prospettore Khazgorm di Bael Modan sta facendo grandi progressi. Oggi ha portato alla luce un fossile che gli studiosi dello scavo ritengono un frammento d'osso di un antico dio. Khazgorm è certo che il fossile sia parte di un mistero più grande. Mentre lui sovrintende al sito di scavo, mi ha affidato il compito di scoprire altri fossili per ricostruire la storia.\n\nIl mio incarico: dirigermi a sud in cerca di altri indizi.", "." },
})
